import{_ as n,o as t,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Zenin Documentation","description":"Find the right Zenin documentation — public user guides, internal engineering and operations docs, and the audit archive.","frontmatter":{"title":"Zenin Documentation","description":"Find the right Zenin documentation — public user guides, internal engineering and operations docs, and the audit archive.","audience":"all","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),a={name:"index.md"};function r(s,e,d,c,l,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="zenin-documentation" tabindex="-1">Zenin Documentation</h1><p>Zenin is a multi-asset investment intelligence workspace for individual investors. This page points you to the right documentation.</p><blockquote><p>Zenin provides research and decision-support tools only. It is <strong>not</strong> investment, tax, legal, or financial advice.</p></blockquote><h2 id="i-am-a-user" tabindex="-1">I am a user</h2><p>Start with the public portal:</p><ul><li><strong><a href="/get-started/what-is-zenin">Get started</a></strong> — what Zenin is, create a workspace, connect data sources, your first portfolio sync, and troubleshooting.</li><li><strong><a href="/use-zenin/portfolio-and-connected-accounts">Use Zenin</a></strong> — portfolio and connected accounts, trades and journal, notifications, watchlists and research, analytics, and the data status glossary.</li></ul><h2 id="i-build-or-operate-zenin" tabindex="-1">I build or operate Zenin</h2><p>Internal engineering and operations documentation lives in the repository, not in this public portal:</p><ul><li><strong>Repository <code>docs/internal/</code></strong> — architecture, portfolio and provider operations, notifications operations, local development, and deployment/incident response.</li><li>These documents are internal-only and are not deployed to the public site.</li></ul><h2 id="i-want-engineering-evidence-audits" tabindex="-1">I want engineering evidence / audits</h2><p>Deep audits and migration plans are retained as historical evidence:</p><ul><li><strong>Repository <code>docs/internal/architecture/audits/</code></strong> — each audit is marked with <code>status</code>, <code>last_verified</code>, and whether it is <code>current</code>, <code>historical</code>, or <code>proposed</code>.</li><li>Audits are evidence of engineering decisions. They are not user guides. Public user documentation is task-oriented and lives in this portal.</li></ul>',12)])])}const g=n(a,[["render",r]]);export{h as __pageData,g as default};
